    // Partially inside
    const mid = Math.floor((start + end) / 2);
    const leftRes = this._query(2 * node + 1, start, mid, L, R);
    const rightRes = this._query(2 * node + 2, mid + 1, end, L, R);

    return this._merge(leftRes, rightRes);
